class BloomFilter:
    """
    A Bloom Filter implementation to probabilistically check for membership of items,
    effectively balancing memory usage and false positive rates.

    The size of the bit array and the number of hash functions are determined based
    on expected items and desired false positive rate, utilizing efficient hashing.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array and number of hash functions
        self.size = self._get_optimal_size(expected_items, false_positive_rate)
        self.num_hashes = self._get_optimal_hash_count(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _get_optimal_size(self, n: int, p: float) -> int:
        """Calculate optimal bit array size based on expected items and false positive rate."""
        if p <= 0 or p >= 1:
            raise ValueError("False positive rate must be between 0 and 1.")
        return math.ceil((n * math.log(p)) / (math.log(1 / (2 ** math.log(2)))))

    def _get_optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate optimal number of hash functions based on bit array size and expected items."""
        if n <= 0:
            raise ValueError("Expected items must be greater than 0.")
        return max(1, math.ceil((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate multiple hash values for the given item using hashlib."""
        result = []
        item_bytes = item.encode('utf-8')
        for i in range(self.num_hashes):
            hash_value = int(hashlib.md5(item_bytes + i.to_bytes(2, byteorder='big')).hexdigest(), 16) % self.size
            result.append(hash_value)
        return result

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter by setting the corresponding bits."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if the item is possibly in the Bloom filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

